import java.util.*; import java.io.*; public class Main { public static void main(String[] args) throws IOException { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); PrintWriter out = new PrintWriter(System.out); String line = br.readLine(); if (line != null) { int t = Integer.parseInt(line.trim()); while (t-- > 0) { StringTokenizer st = new StringTokenizer(br.readLine()); int x = Integer.parseInt(st.nextToken()); int n = Integer.parseInt(st.nextToken()); int pointsPerTestCase = x / 10; int totalScore = pointsPerTestCase * n; out.println(totalScore); } } out.flush(); out.close(); } }